custom_fields.title:
[[[
  const name = entity.attributes.friendly_name || entity.entity_id;
  const shortened = name
    .replace(/\b(?:Wohnzimmer(?: Neu)?|Küche|Schlafzimmer|Badezimmer|Büro|Flur|IKEA|Shelly|Meros|Refoss|Energy|Energie|kWh|Leistung|Power)\b/ig, ' ')
    .replace(/\s+Led enable\b/ig, ' ')
    .replace(/\s{2,}/g, ' ')
    .replace(/^[\s,;:/-]+|[\s,;:/-]+$/g, '')
    .trim();
  return shortened || name;
]]]

custom_fields.values:
[[[
 const p=states['sensor.example_refrigerator_power'];
 const e=states['sensor.example_refrigerator_energy'];
 const fridgeTemp=states['number.example_refrigerator_temperature'];
 const freezerTemp=states['number.example_freezer_temperature'];
 const power=p && !['unknown','unavailable'].includes(p.state) ? Math.round(Number(p.state)).toLocaleString('de-DE') + ' ' + (p.attributes.unit_of_measurement || 'W') : '— W';
 const energy=e && !['unknown','unavailable'].includes(e.state) ? Math.round(Number(e.state)).toLocaleString('de-DE') + ' ' + (e.attributes.unit_of_measurement || 'kWh') : '— kWh';
 const temp = x => x && !['unknown','unavailable'].includes(x.state) ? Number(x.state).toLocaleString('de-DE') + '°' : '—';
 return '<div style="font-size:16px;font-weight:700;">'+power+'</div><div style="font-size:13px;font-weight:400;">'+energy+'</div><div style="margin-top:6px;font-size:12px;line-height:1.55;color:var(--secondary-text-color);"><span style="display:block"><ha-icon icon="mdi:fridge" style="width:14px;height:14px;vertical-align:-2px;margin-right:4px"></ha-icon>'+temp(fridgeTemp)+'</span><span style="display:block"><ha-icon icon="mdi:snowflake" style="width:14px;height:14px;vertical-align:-2px;margin-right:4px"></ha-icon>'+temp(freezerTemp)+'</span></div>';
]]]

series.data_generator:
return (// Calendar-hour counts from confirmed off -> on transitions. Request a full
// extra hour so the first visible partial hour has its complete evidence.
// The initial history state is a seed, never an opening event.
async function fridgeDoorHistory(entity,start,end,hass){
 const hour=3600000,until=Math.min(end.getTime(),Date.now());
 const since=Math.floor(start.getTime()/hour)*hour-hour;
 const rows=await hass.callApi('GET','history/period/'+new Date(since).toISOString()+'?filter_entity_id='+encodeURIComponent(entity.entity_id)+'&end_time='+new Date(until).toISOString()+'&minimal_response&no_attributes');
 const history=rows[0]||[];if(!history.length)return [];
 const bins=new Map();let previous=null;
 for(const row of history){
  const time=Date.parse(row.last_changed||row.last_updated),key=Math.floor(time/hour)*hour;
  if(previous==='off'&&row.state==='on')bins.set(key,(bins.get(key)||0)+1);
  previous=row.state;
 }
 const points=[];
 for(let time=Math.floor(start.getTime()/hour)*hour;time<until;time+=hour){
  const right=Math.min(time+hour-1,until);
  // A gap in reported sensor availability makes that hour unknown.
  const evidence=history.filter(row=>Date.parse(row.last_changed||row.last_updated)<right);
  const seed=history.filter(row=>Date.parse(row.last_changed||row.last_updated)<=time).at(-1);
  const last=evidence.at(-1),valid=last&&seed&&['on','off'].includes(last.state)&&['on','off'].includes(seed.state);
  const gap=history.some(row=>{const t=Date.parse(row.last_changed||row.last_updated);return t>=time&&t<=right&&!['on','off'].includes(row.state);});
  const value=valid&&!gap?(bins.get(time)||0):null;
  // One centered column for each calendar hour; current hour is partial.
  points.push([time+hour/2,value]);
 }
 return points;
}
)(entity,start,end,hass);

